document.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const ids=['volumen','categorias','frecuencia','permanencia','geografia'];const t=TempoTools.puntosTitulares(Number($('titulares').value));const vals=[t,...ids.map(id=>$ (id).value==='x'?null:Number($(id).value))];const r=TempoTools.escala(vals);const direct=$('directo').value;const automatic=direct==='si';const large=automatic||(r&&r.granEscala);const gap=t===null;let g=automatic?'You have identified a direct large-scale case. Whether it applies must be confirmed; that case does not depend on the score.':r?(r.granEscala?'The calculation reaches the large-scale threshold.':'The calculation is below the large-scale threshold.'):'The calculation cannot be completed with the information provided.';if(direct==='nose')g+=' The possible direct classification is still pending, whatever the score.';if(direct==='no'&&r&&!r.granEscala)g+=' This result depends on there being no omitted direct case.';const signal=$('publico').value==='si'||$('sector').value==='si'||large;const d=signal?'Your answers point to a reason to review the mandatory appointment of a DPO. Confirm the case and the DPO’s requirements.':'We have not confirmed a ground with these answers. This is not an exemption: review your activity and the other legal cases.';show('<p class="eyebrow">Separate results</p><h2>Large scale</h2><p>'+g+'</p>'+(r?'<p class="amount">'+String(r.total)+' points</p><p>Threshold: 6 points. No condition of exceeding 1,000 people is added.</p><dl>'+['People','Types of data','Categories','Frequency','Duration','Geography'].map((label,i)=>'<dt>'+label+'</dt><dd>'+String(vals[i])+'</dd>').join('')+'</dl>':'<p>'+ (gap?'The text of article 8 leaves no express band for values between 100,001 and 100,999 data subjects. This tool does not fill that gap on its own; request a review of the applicable criterion.':'Complete the unknown variables to obtain the score.')+'</p>')+'<h2>Data Protection Officer</h2><p>'+d+'</p><p>Having a DPO does not certify the compliance of the whole organization. The external arrangement is a hiring option, not a general obligation.</p><p>Keep the assessment and review it when the processing changes. This calculation provides guidance; it does not verify your data, documents or the correct choice of categories.</p>'+finish());});